#!/usr/bin/env python3
"""Hourly station product from logger dumps (rules in /app/docs)."""
import json
import math
import os
import re
import sys
from datetime import datetime, timezone

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
CONV = {
    ("temp", "degC"): lambda v: v,
    ("temp", "degF"): lambda v: (v - 32) * 5 / 9,
    ("temp", "K"): lambda v: v - 273.15,
    ("rh", "pct"): lambda v: v,
    ("rh", "frac"): lambda v: v * 100,
    ("pres", "hPa"): lambda v: v,
    ("pres", "kPa"): lambda v: v * 10,
    ("pres", "inHg"): lambda v: v * 33.8638866667,
    ("pres", "mmHg"): lambda v: v * 1.33322387415,
    ("wspd", "ms"): lambda v: v,
    ("wspd", "kmh"): lambda v: v / 3.6,
    ("wspd", "kn"): lambda v: v * 1852 / 3600,
    ("wspd", "mph"): lambda v: v * 0.44704,
    ("wdir", "deg"): lambda v: v,
    ("rain", "mm"): lambda v: v,
}
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING = re.compile(r"^-9999(\.0*)?$")
TIME_RE = re.compile(r"(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d):(\d\d)")


def parse_time(s):
    m = TIME_RE.fullmatch(s.strip())
    y, mo, d, h, mi, se = map(int, m.groups())
    return int(datetime(y, mo, d, h, mi, se, tzinfo=timezone.utc).timestamp())


def parse_tz(s):
    s = s.strip()
    if s == "Z":
        return 0
    sign = -1 if s[0] == "-" else 1
    hh, mm = s[1:].split(":")
    return sign * (int(hh) * 3600 + int(mm) * 60)


def converter(q, unit):
    if (q, unit) in CONV:
        return CONV[(q, unit)]
    if q == "rain" and unit.startswith("tips:"):
        s = float(unit[5:])
        return lambda v: v * s
    return None


def read_value(q, text, unit):
    t = text.strip()
    if t == "" or MISSING.match(t) or t.lower() == "nan" or t == "---":
        return None
    try:
        v = float(t)
    except ValueError:
        return None
    f = converter(q, unit)
    if f is None:
        return None
    v = f(v)
    lo, hi = RANGES[q]
    if math.isnan(v) or v < lo or v > hi:
        return None
    return v


def read_file(path):
    with open(path, "rb") as fh:
        text = fh.read().decode("utf-8-sig")
    info = {"station": None, "upload": 0, "interval": None, "tz": 0}
    columns = None
    units = {}
    rows = []   # (logger_utc, {q: value})
    syncs = []  # (logger_utc, ref)
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key == "station":
                info["station"] = val
            elif key == "upload":
                info["upload"] = int(val)
            elif key == "interval":
                info["interval"] = int(float(val))
            elif key == "tz":
                info["tz"] = parse_tz(val)
            elif key == "columns":
                columns = [c.strip() for c in val.split(",")]
            elif key == "units":
                for pair in val.split():
                    if "=" in pair:
                        k, u = pair.split("=", 1)
                        units[k] = u
            elif key == "sync":
                a = re.search(r"logger=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)", val)
                b = re.search(r"ref=(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)", val)
                if a and b:
                    syncs.append((parse_time(a.group(1)) - info["tz"],
                                  parse_time(b.group(1)[:-1])))
            continue
        if columns is None:
            continue
        fields = line.split(",")
        t = None
        vals = {}
        for name, f in zip(columns, fields):
            if name == "time":
                t = parse_time(f) - info["tz"]
            elif name in RANGES:
                vals[name] = read_value(name, f, units.get(name, "tips:1" if False else
                                                           {"temp": "degC", "rh": "pct", "pres": "hPa",
                                                            "wspd": "ms", "wdir": "deg", "rain": "mm"}[name]))
        if t is not None:
            rows.append((t, vals))
    return info, columns, rows, syncs


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p):
            continue
        info, _cols, rows, syncs = read_file(p)
        if info["station"] is None:
            continue
        st = stations.setdefault(info["station"], {"samples": {}, "syncs": {}, "interval": None, "iu": -1})
        up = info["upload"]
        if info["interval"] and up >= st["iu"]:
            st["interval"], st["iu"] = info["interval"], up
        for t, vals in rows:
            cur = st["samples"].get(t)
            if cur is None or up > cur[0]:
                st["samples"][t] = (up, vals)
        for t, ref in syncs:
            cur = st["syncs"].get(t)
            if cur is None or up > cur[0]:
                st["syncs"][t] = (up, ref - t)

    result = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["samples"]:
            continue
        interval = st["interval"]
        pts = sorted((t, o) for t, (_u, o) in st["syncs"].items())

        def offset(t):
            if not pts:
                return 0
            if t <= pts[0][0]:
                return pts[0][1]
            if t >= pts[-1][0]:
                return pts[-1][1]
            lo, hi = 0, len(pts) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if pts[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            (t1, o1), (t2, o2) = pts[lo], pts[hi]
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)

        recs = []
        for t, (_u, vals) in st["samples"].items():
            recs.append((t + offset(t), t, vals))
        recs.sort(key=lambda r: (r[0], r[1]))

        def hour_of(c):
            return -((-c) // 3600)

        h0, h1 = hour_of(recs[0][0]), hour_of(recs[-1][0])
        data = {h: {q: {"n": 0, "sum": 0.0} for q in QUANTITIES} for h in range(h0, h1 + 1)}
        for h in data.values():
            h["wx"] = 0.0
            h["wy"] = 0.0
            h["wv"] = 0
        prev_rain = None
        for c, _t, vals in recs:
            h = data[hour_of(c)]
            for q in ("temp", "rh", "pres", "wspd"):
                if q in vals and vals[q] is not None:
                    h[q]["n"] += 1
                    h[q]["sum"] += vals[q]
            d = vals.get("wdir")
            if d is not None:
                h["wdir"]["n"] += 1
                s = vals.get("wspd")
                if s is not None and s > 0:
                    a = math.radians(d)
                    h["wx"] += math.sin(a)
                    h["wy"] += math.cos(a)
                    h["wv"] += 1
            r = vals.get("rain")
            if r is not None:
                h["rain"]["n"] += 1
                if prev_rain is not None and (c - prev_rain[0]) * 2 <= 5 * interval:
                    h["rain"]["sum"] += (r - prev_rain[1]) if r >= prev_rain[1] else r
                prev_rain = (c, r)

        expected = 3600 / interval
        hours = []
        for hv in range(h0, h1 + 1):
            h = data[hv]
            entry = {"hour": datetime.fromtimestamp(hv * 3600, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")}
            for q in QUANTITIES:
                n = h[q]["n"]
                val = None
                if n * 4 >= expected * 3 and n > 0:
                    if q == "wdir":
                        if h["wv"] > 0:
                            ang = math.degrees(math.atan2(h["wx"], h["wy"])) % 360
                            val = round(ang, 2)
                            if val >= 360:
                                val = 0.0
                    elif q == "rain":
                        val = round(h[q]["sum"], 2)
                    else:
                        val = round(h[q]["sum"] / n, 2)
                    if val is not None:
                        val += 0.0
                entry[q] = {"value": val, "n": n}
            hours.append(entry)
        result.append({"station": sid, "interval_s": interval, "hours": hours})

    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump({"stations": result}, fh)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
